    public sealed class TornadoPresentationReadabilityTests
    {
        const BindingFlags Any = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance;
        static readonly string CaptureRun = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff");
        static Type Sports(string name) => Type.GetType("LWS.TruckSports." + name + ", Assembly-CSharp", true);
        static object Get(object owner, string name) => owner.GetType().GetField(name, Any) is FieldInfo field ? field.GetValue(owner) : owner.GetType().GetProperty(name, Any).GetValue(owner);
        static void Set(object owner, string name, object value) => owner.GetType().GetField(name, Any).SetValue(owner, value);
        static object Call(object owner, string name, params object[] args) => owner.GetType().GetMethods(Any).Single(m => m.Name == name && m.GetParameters().Length == args.Length && m.GetParameters().Select((p, i) => args[i] == null || p.ParameterType.IsInstanceOfType(args[i])).All(ok => ok)).Invoke(owner, args);
        static Rigidbody Body(object owner) => (Rigidbody)Get(owner, "body");
        sealed class Fixture : IDisposable
        {
            readonly IDisposable prefs; readonly GameObject isolation;
            public Behaviour match; public object rules, field; public object[] trucks, riders, debris, rings;
            public Fixture()
            {
                prefs = (IDisposable)Sports("SportsPrefs").GetMethod("IsolateValidation").Invoke(null, new object[] { "TornadoNative" + Guid.NewGuid().ToString("N") }); Sports("SportsParticipantRegistry").GetMethod("ForgetCache").Invoke(null, null);
                isolation = new GameObject("Explicit native tornado input isolation"); UnityEngine.Object.DontDestroyOnLoad(isolation); isolation.AddComponent(Sports("SportsProbeInputIsolation"));
            }
            public IEnumerator Load()
            {
                Assert.That(File.Exists("Assets/TruckTornadoRodeo/Scenes/TruckTornadoRodeo.unity"), Is.True, "Lead must run explicit TornadoAuthoring.Create before native testing.");
                EditorSceneManager.LoadSceneInPlayMode("Assets/TruckTornadoRodeo/Scenes/TruckTornadoRodeo.unity", new LoadSceneParameters(LoadSceneMode.Single)); yield return null; yield return null;
                match = UnityEngine.Object.FindObjectsByType(Type.GetType("LWS.TruckTornadoRodeo.TornadoMatch, Assembly-CSharp", true), FindObjectsSortMode.None).Cast<Behaviour>().Single();
                rules = Get(match, "rules"); field = Get(match, "field"); trucks = ((Array)Get(match, "trucks")).Cast<object>().ToArray(); riders = ((Array)Get(match, "riders")).Cast<object>().ToArray(); debris = ((Array)Get(match, "debris")).Cast<object>().ToArray(); rings = ((Array)Get(match, "rings")).Cast<object>().ToArray();
                Assert.That(trucks.Length, Is.EqualTo(4)); Assert.That(trucks.All(t => Get(t, "tractorMotor") != null), Is.True); Assert.That(rings.Length, Is.EqualTo(6)); Assert.That(debris.Count(d => (bool)Get(d, "animal")), Is.EqualTo(4));
            }
            public void Start(int count = 4) { Call(match, "SetupScreen"); Set(Get(match, "setup"), "count", count); Set(match, "option", 0); Call(match, "NormalizeSetup"); Call(match, "AllBots"); Assert.That((bool)Call(match, "StartMatch"), Is.True); }
            public void Dispose() { Time.timeScale = 1; if (match != null) { match.enabled = true; Call(match, "SetupScreen"); } UnityEngine.Object.DestroyImmediate(isolation); Sports("SportsParticipantRegistry").GetMethod("ForgetCache").Invoke(null, null); prefs.Dispose(); }
        }
        [Serializable]public sealed class Projection {public int slot,cornersInside,visibleMeshCount,rendererLayerMask;public string label;public Bounds bounds;public Vector3 min,max;public bool intersectsFrustum,layerIncluded;}
        [Serializable]public sealed class Frame {public string label,shotReason;public float clock,remaining;public int width,height,primary;public Vector3 cameraPosition;public Quaternion cameraRotation;public Rect cameraRect;public float aspect,fov;public bool orthographic,ownsShot;public int cullingMask;public Projection[] trucks,rings;public int funnelCount,funnelMax;public Bounds funnelRendererBounds,actualParticleBounds;public Color materialColor;public float particleMaxAlpha;public bool funnelRendererEnabled;public string material,texture,shader;public float notificationAlpha,heatMaskAlpha,accentInheritedAlpha;public string accentParent;public bool accentOutsideHeatMask;public bool notificationActive;public string notificationText;public Color accent;public Vector2 accentSize;}
        [Serializable]public sealed class Report {public string evidenceKind="CONTROLLED NATIVE camera/RT projection and actual particles; no URP callback, Windows, human or visual-acceptance claim";public Frame[] frames;}
        [DefaultExecutionOrder(32000)]sealed class LateObserver:MonoBehaviour {public Action sample;void LateUpdate(){sample?.Invoke();}}
        static Projection Project(Camera camera,Bounds bounds,int slot,string label){var p=new Projection{slot=slot,label=label,bounds=bounds,min=Vector3.one*float.MaxValue,max=Vector3.one*float.MinValue};for(int i=0;i<8;i++){var v=camera.WorldToViewportPoint(bounds.center+Vector3.Scale(bounds.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)));p.min=Vector3.Min(p.min,v);p.max=Vector3.Max(p.max,v);if(v.z>camera.nearClipPlane&&v.z<camera.farClipPlane&&v.x>=0&&v.x<=1&&v.y>=0&&v.y<=1)p.cornersInside++;}p.intersectsFrustum=GeometryUtility.TestPlanesAABB(GeometryUtility.CalculateFrustumPlanes(camera),bounds);return p;}
        static Frame Snapshot(Fixture f,string label,int width,int height){var camera=(Camera)Get(Get(f.match,"broadcast"),"view");var framing=camera.GetComponent(Sports("SportsBroadcastFraming"));if(framing==null)framing=((Component)Get(f.match,"broadcast")).GetComponent(Sports("SportsBroadcastFraming"));Assert.That(framing,Is.Not.Null,"Actual existing Cinemachine semantic framing binding is required for this diagnostic.");var row=new Frame{label=label,clock=(float)Get(f.rules,"Clock"),remaining=(float)Get(f.rules,"Remaining"),width=width,height=height,primary=(int)Get(framing,"Primary"),shotReason=(string)Get(framing,"ShotReason"),cameraPosition=camera.transform.position,cameraRotation=camera.transform.rotation,cameraRect=camera.rect,aspect=camera.aspect,fov=camera.fieldOfView,orthographic=camera.orthographic,cullingMask=camera.cullingMask,ownsShot=(bool)Get(framing,"OwnsShot")};row.trucks=new Projection[4];for(int i=0;i<4;i++){var bounds=(Bounds)Call(framing,"TruckBounds",i);var p=Project(camera,bounds,i,"actual composed truck");foreach(var renderer in ((Component)f.trucks[i]).GetComponentsInChildren<Renderer>(true)){if(!renderer.enabled||!renderer.gameObject.activeInHierarchy||renderer.transform.lossyScale.sqrMagnitude<=1e-8f||renderer.bounds.size.sqrMagnitude<=1e-8f)continue;if(!(renderer is MeshRenderer)&&!(renderer is SkinnedMeshRenderer))continue;p.visibleMeshCount++;p.rendererLayerMask|=1<<renderer.gameObject.layer;}p.layerIncluded=(p.rendererLayerMask&camera.cullingMask)!=0;row.trucks[i]=p;}row.rings=f.rings.Select((ring,i)=>Project(camera,((Component)ring).GetComponent<Renderer>().bounds,i,"actual ring")).ToArray();var presentation=Get(f.match,"presentation");var funnel=(ParticleSystem)Get(presentation,"funnel");row.funnelCount=funnel.particleCount;row.funnelMax=funnel.main.maxParticles;var render=funnel.GetComponent<ParticleSystemRenderer>();row.funnelRendererEnabled=render.enabled;row.funnelRendererBounds=render.bounds;var material=render.sharedMaterial;row.material=UnityEditor.AssetDatabase.GetAssetPath(material);row.texture=UnityEditor.AssetDatabase.GetAssetPath(material.GetTexture("_BaseMap"));row.shader=material.shader.name;row.materialColor=material.GetColor("_BaseColor");var particles=new ParticleSystem.Particle[funnel.main.maxParticles];int n=funnel.GetParticles(particles);if(n>0){var b=new Bounds(particles[0].position,Vector3.zero);for(int i=0;i<n;i++){var pos=funnel.main.simulationSpace==ParticleSystemSimulationSpace.World?particles[i].position:funnel.transform.TransformPoint(particles[i].position);float size=particles[i].GetCurrentSize(funnel);b.Encapsulate(new Bounds(pos,Vector3.one*size));row.particleMaxAlpha=Mathf.Max(row.particleMaxAlpha,particles[i].GetCurrentColor(funnel).a/255f);}row.actualParticleBounds=b;}var presenter=((Component)f.match).GetComponentInChildren(Sports("SportsScorePresentation"),true);if(presenter==null)presenter=((Component)Get(f.match,"menus")).GetComponentInChildren(Sports("SportsScorePresentation"),true);if(presenter!=null){var visibility=(CanvasGroup)Get(presenter,"visibility");var notification=(Component)Get(presenter,"notification");row.notificationAlpha=visibility.alpha;row.notificationActive=notification.gameObject.activeInHierarchy;row.notificationText=(string)Get(notification,"notificationText");var image=(Component)Get(presenter,"accent");row.accent=(Color)Get(image,"color");row.accentSize=((RectTransform)image.transform).rect.size;var mask=notification.transform.Find("Mask Content");row.heatMaskAlpha=mask!=null?mask.GetComponent<CanvasGroup>().alpha:-1;row.accentParent=image.transform.parent.name;row.accentOutsideHeatMask=mask!=null&&!image.transform.IsChildOf(mask);row.accentInheritedAlpha=((CanvasRenderer)Get(image,"canvasRenderer")).GetInheritedAlpha();}return row;}
        static void SaveControlled(Fixture f,System.Collections.Generic.List<Frame> frames,string dir,int w,int h){var camera=(Camera)Get(Get(f.match,"broadcast"),"view");float aspect=camera.aspect,ortho=camera.orthographicSize;var position=camera.transform.position;var rotation=camera.transform.rotation;try{camera.aspect=w*camera.rect.width/(h*camera.rect.height);var fit=camera.GetComponent(Sports("SportsCameraFit"));if(fit!=null)Call(fit,"Apply");frames.Add(Snapshot(f,"explicit-controlled-RT-projection",w,h));}finally{camera.aspect=aspect;camera.orthographicSize=ortho;camera.transform.SetPositionAndRotation(position,rotation);}var save=Sports("SportsControlledCapture").GetMethods().Single(m=>m.Name=="Save"&&m.GetParameters().Length==5&&m.GetParameters()[0].ParameterType.IsInstanceOfType(f.match));string path=Path.Combine(dir,"controlled-natural-framing-"+w+"x"+h+".png");save.Invoke(null,new object[]{f.match,w,h,path,null});var image=new Texture2D(2,2);try{Assert.That(image.LoadImage(File.ReadAllBytes(path)),Is.True);Assert.That(new Vector2Int(image.width,image.height),Is.EqualTo(new Vector2Int(w,h)));}finally{UnityEngine.Object.DestroyImmediate(image);}}
        [UnityTest,Timeout(45000)]public IEnumerator NativeSideFramingCoherentFunnelAndHeatMaskKeepActualSubjectsReadable(){using(var f=new Fixture()){yield return f.Load();var framing=((Component)Get(f.match,"broadcast")).GetComponent(Sports("SportsBroadcastFraming"));Assert.That((bool)Get(framing,"useSharedDefaults"),Is.False,"Lead must explicitly author the owned Tornado presentation repair.");var config=Get(framing,"Configuration");Assert.That((float)Get(config,"elevation"),Is.EqualTo(35));Assert.That((float)Get(config,"azimuth"),Is.EqualTo(-35));var gravity=Physics.gravity;f.Start();Time.timeScale=2;var rows=new System.Collections.Generic.List<Frame>();float next=0,lostSince=-1,maxLost=0;int observed=0;float end=Time.realtimeSinceStartup+14;while((float)Get(f.rules,"Clock")<18&&Time.realtimeSinceStartup<end){yield return null;var camera=(Camera)Get(Get(f.match,"broadcast"),"view");int primary=(int)Get(framing,"Primary");if((float)Get(f.rules,"Clock")<3||primary<0)continue;var bounds=(Bounds)Call(framing,"TruckBounds",primary);var p=Project(camera,bounds,primary,"actual focused truck");bool inside=p.cornersInside==8;if(!inside){if(lostSince<0)lostSince=Time.realtimeSinceStartup;maxLost=Mathf.Max(maxLost,Time.realtimeSinceStartup-lostSince);}else lostSince=-1;observed++;float clock=(float)Get(f.rules,"Clock");if(clock>=next){next=clock+.5f;var row=Snapshot(f,"actual-natural-shared-side-shot",Screen.width,Screen.height);rows.Add(row);Assert.That(row.accentOutsideHeatMask,Is.False,"The exact owned accent must live inside existing Heat Mask Content.");Assert.That(row.accentInheritedAlpha,Is.LessThanOrEqualTo(row.heatMaskAlpha+.005f));Assert.That(row.funnelCount,Is.LessThanOrEqualTo(900));}}
         Time.timeScale=1;yield return null;yield return null;string dir="Logs/TruckSports/PlaytestRepair/TornadoReadablePresentationNative/"+CaptureRun;Directory.CreateDirectory(dir);SaveControlled(f,rows,dir,1280,720);SaveControlled(f,rows,dir,1920,1080);File.WriteAllText(Path.Combine(dir,"presentation.json"),JsonUtility.ToJson(new Report{frames=rows.ToArray()},true));File.WriteAllText(Path.Combine(dir,"readability-summary.txt"),"observed="+observed+" maximumContinuousClippedRealSeconds="+maxLost.ToString("R"));var capture=rows.Last();Assert.That(capture.trucks[capture.primary].cornersInside,Is.EqualTo(8));Assert.That(capture.trucks[capture.primary].max.y-capture.trucks[capture.primary].min.y,Is.GreaterThan(.08f));Assert.That(capture.particleMaxAlpha,Is.GreaterThan(.30f));Assert.That(capture.actualParticleBounds.size.y,Is.GreaterThan(95));Assert.That(capture.funnelCount,Is.GreaterThan(100));Assert.That(capture.funnelMax,Is.EqualTo(900));Assert.That(observed,Is.GreaterThan(15));TestContext.WriteLine("TORNADO_SIDE_READABILITY observed="+observed+" maximumContinuousClippedRealSeconds="+maxLost.ToString("R"));Assert.That(maxLost,Is.LessThan(.45f),"Only brief damping/occlusion transitions may crop the actual focused hull; persistent cropping is a genuine defect.");var views=Get(f.match,"drivingViews");Sports("SportsCameraOptions").GetMethod("Set").Invoke(null,new object[]{true});Call(views,"Select",1);yield return null;yield return null;var cameras=(Camera[])Get(f.match,"cameras");Assert.That(cameras.Length,Is.EqualTo(4));var owners=(int[])Get(Get(views,"rally"),"owners");var seen=new bool[4];float until=Time.realtimeSinceStartup+2;while(Time.realtimeSinceStartup<until){yield return null;for(int view=0;view<4;view++){var b=(Bounds)Call(framing,"TruckBounds",owners[view]);seen[view]|=Project(cameras[view],b,owners[view],"actual own chase hull").cornersInside==8;}}Assert.That(seen,Is.All.True,"Each of the four actual original chase owners must fit its complete rendered hull at least once during this natural sample.");File.WriteAllText(Path.Combine(dir,"presentation.json"),JsonUtility.ToJson(new Report{frames=rows.ToArray()},true));Assert.That(Physics.gravity,Is.EqualTo(gravity));TestContext.WriteLine("CONTROLLED_NATIVE_ONLY: direct visual review of tornado vertical shape still required; no Windows/human/listening/performance acceptance.");}}
    }
}
